export function rpxCertificateRenewalScript(slug: string): string {
  // Match the tenant unit name generated by ts-cloud.
  const safeSlug = (slug || 'app').replace(/[^a-z0-9._-]+/gi, '-')
  return [
    `unit='rpx-cert-renew-${safeSlug}.service'`,
    'status=0',
    'systemctl start "$unit" || status=$?',
    'if [ "$status" -ne 0 ]; then exec 1>&2; fi',
    `journalctl -u "$unit" -n 20 --no-pager -o cat 2>/dev/null | grep -E 'Certificate written|Skipping|failed|[Ee]rror|\\[ts-cloud\\]' | tail -5`,
    'exit "$status"',
  ].join('\n')
}
